<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Sorting Visualizer</title>
<style>
    body {
        background-color: #121212; /* Dark Theme */
        color: #e0e0e0;
        font-family: sans-serif;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        height: 100vh;
        margin: 0;
    }

    #bars {
        display: flex;
        align-items: flex-end; /* Align bars to bottom */
        gap: 2px;
        width: 80%;
        max-width: 600px;
        height: 300px;
        background-color: #1e1e1e;
        border: 1px solid #333;
        padding: 5px;
        margin-bottom: 20px;
    }

    .bar {
        flex-grow: 1;
        background-color: #4a90e2; /* Default bar color */
        min-width: 5px;
        border-radius: 3px 3px 0 0;
        transition: height 0.1s linear, background-color 0.1s ease;
    }

    button {
        padding: 12px 24px;
        font-size: 1rem;
        margin: 5px;
        cursor: pointer;
        background-color: #333;
        color: white;
        border: none;
        border-radius: 6px;
    }

    button:hover {
        background-color: #4a90e2;
    }

    button:active {
        transform: scale(0.95);
    }
</style>
</head>
<body>

<div id="bars"></div>

<button id="sort">Sort</button>
<button id="shuffle">Shuffle</button>
<button id="reset">Reset</button>

<script>
// --- State & Logic ---

let arr = []; // The array of numbers currently visualized.
const container = document.getElementById('bars');

// Sorting state variables (persist between calls) - Bubble Sort logic
let _i = 0; 
let _j = 0;

// --- Viz API Implementation ---

window.viz = {
    // Returns current array of numbers.
    array: () => arr, 

    // Set the array (and redraw).
    setArray(a) {
        if (!a || a.length === 0) {
            arr = [];
            renderBars();
            return;
        }

        arr = [...a]; // copy to avoid mutating external reference directly

        _i = 0;
        _j = 0;

        renderBars();
    },

    // Advance the sort ONE step (comparison/swap). 
    // Returns true if fully sorted, false otherwise.
    sortStep: function() {
        const n = arr.length;

        // Base cases
        if (n <= 1) return true;

        // Check end of current outer loop pass for Bubble Sort logic
        let passEnd = n - 1 - _i;

        // If we have reached the end of the inner loop iteration
        if (_j >= passEnd) {
            // Move to next element in array (outer loop increment)
            _i++; 
            _j = 0;

            // Check if all passes are complete. Bubble sort typically runs up to n-1 passes.
            if (_i >= n) {
                return true; 
            }

            // Return false to continue in next step call (next comparison will be at j=0 of new pass)
            return false;
        }

        const idx1 = _j;
        const idx2 = _j + 1;

        if (idx1 < n && idx2 < n) {
            // Perform comparison/swap logic on the array

            let swapOccurred = false;

            if (arr[idx1] > arr[idx2]) {
                [arr[idx1], arr[idx2]] = [arr[idx2], arr[idx1]];
                swapOccurred = true;
            }

            // If values changed, re-render DOM to reflect new heights/order.
            // This ensures visual representation matches array state after swaps.
            if (swapOccurred) {
                renderBars(); 
            } else {
                // Optional: Could update styling here without full re-render for smoother animation.
                // Skipping to keep code minimal and robust with rebuild logic.
            }

            _j++; // Advance index for next comparison step
        } 

        return false; // Not fully sorted yet (unless check at top handles early exit)
    },

    // Returns boolean: is the array ascending?
    sorted: () => {
        if (arr.length <= 1) return true;
        for (let k = 0; k < arr.length - 1; k++) {
            if (arr[k] > arr[k + 1]) return false;
        }
        return true;
    }
};

// --- Helper Functions ---

function renderBars() {
    container.innerHTML = ''; // Clear previous bars

    if (arr.length === 0) return;

    // Dynamically find max to scale heights relative to current data range.
    const maxVal = Math.max(...arr); 
    // Avoid division by zero and ensure visible height for non-zero values.
    let hScale = container.clientHeight / (maxVal || 1);

    for (let val of arr) {
        const bar = document.createElement('div');
        bar.className = 'bar';

        // Height calculation: max(val, minPixelHeight). 
        // Ensure minimum height to be visible.
        const h = Math.max(4, val * hScale); 
        bar.style.height = `${h}px`;

        container.appendChild(bar);
    }
}

// --- Event Listeners ---

document.getElementById('shuffle').onclick = () => {
    // Generate a randomized array of numbers between 0 and 100.
    const len = Math.floor(Math.random() * 20) + 5; 
    let shuffledArr = [];
    for(let k=0; k<len; k++) {
        shuffledArr.push(Math.floor(Math.random() * 100));
    }
    window.viz.setArray(shuffledArr);
};

document.getElementById('reset').onclick = () => {
    // Clear the bars and reset state.
    window.viz.setArray([]);
};

// Animate sorting: call viz.sortStep until sorted.
document.getElementById('sort').onclick = async function() {
    while (!window.viz.sorted()) {
        window.viz.sortStep();
        await new Promise(resolve => setTimeout(resolve, 30)); // Animation delay to see steps
    }
};

// Initialize with some bars on load (optional but good)
window.viz.setArray([20, 45, 12, 67, 89, 33, 55, 22, 90, 1]);

</script>
</body>
</html>
